/** Host-side persistence for selectable image-generation profiles. */
import { promises as fs } from 'node:fs'
import { homedir } from 'node:os'
import path from 'node:path'
import { randomUUID } from 'node:crypto'
import type { ImageGenProfile, ImageGenProfileInput } from './protocol.ts'

const DIR = path.join(homedir(), '.dsh', 'dsh-imagegen')
const FILE = path.join(DIR, 'profiles.json')

interface StoredProfile {
  id: string
  name: string
  apiUrl: string
  model: string
  apiKey: string
}

let tail: Promise<void> = Promise.resolve()
function serialize<T>(operation: () => Promise<T>): Promise<T> {
  const next = tail.then(operation, operation)
  tail = next.then(() => undefined, () => undefined)
  return next
}

function valid(value: unknown): value is StoredProfile {
  if (value === null || typeof value !== 'object') return false
  const p = value as Partial<StoredProfile>
  return typeof p.id === 'string' && typeof p.name === 'string' && typeof p.apiUrl === 'string'
    && typeof p.model === 'string' && typeof p.apiKey === 'string'
}

async function readAll(): Promise<StoredProfile[]> {
  try {
    const parsed: unknown = JSON.parse(await fs.readFile(FILE, 'utf8'))
    return parsed !== null && typeof parsed === 'object' && Array.isArray((parsed as { profiles?: unknown }).profiles)
      ? (parsed as { profiles: unknown[] }).profiles.filter(valid)
      : []
  } catch { return [] }
}

async function writeAll(profiles: StoredProfile[]): Promise<void> {
  await fs.mkdir(DIR, { recursive: true })
  await fs.writeFile(FILE, JSON.stringify({ profiles }, null, 2), 'utf8')
}

function publicProfile(profile: StoredProfile): ImageGenProfile {
  return { id: profile.id, name: profile.name, apiUrl: profile.apiUrl, model: profile.model, keySet: profile.apiKey.trim() !== '' }
}

export async function listProfiles(): Promise<ImageGenProfile[]> {
  return (await readAll()).map(publicProfile)
}

/** Migrate the old single endpoint/key into one selectable profile once. */
export async function ensureLegacyProfile(legacy: { apiUrl: string; apiKey: string }): Promise<ImageGenProfile[]> {
  return serialize(async () => {
    let profiles = await readAll()
    if (profiles.length === 0 && (legacy.apiUrl.trim() !== '' || legacy.apiKey.trim() !== '')) {
      profiles = [{
        id: 'legacy-default',
        name: '默认配置',
        apiUrl: legacy.apiUrl.trim(),
        model: 'fal-ai/gpt-image-2',
        apiKey: legacy.apiKey,
      }]
      await writeAll(profiles)
    }
    return profiles.map(publicProfile)
  })
}

export async function saveProfile(input: ImageGenProfileInput, legacy?: { apiUrl: string; apiKey: string }): Promise<ImageGenProfile[]> {
  return serialize(async () => {
    let profiles = await readAll()
    const id = input.id?.trim() || randomUUID()
    const existing = profiles.find(profile => profile.id === id)
    const apiKey = input.apiKey?.trim() || existing?.apiKey || (profiles.length === 0 ? legacy?.apiKey ?? '' : '')
    const profile: StoredProfile = {
      id,
      name: input.name.trim() || '默认配置',
      apiUrl: input.apiUrl.trim(),
      model: input.model.trim() || 'fal-ai/gpt-image-2',
      apiKey,
    }
    profiles = existing === undefined ? [...profiles, profile] : profiles.map(item => item.id === id ? profile : item)
    await writeAll(profiles)
    return profiles.map(publicProfile)
  })
}

export async function removeProfile(id: string): Promise<ImageGenProfile[]> {
  return serialize(async () => {
    const profiles = (await readAll()).filter(profile => profile.id !== id)
    await writeAll(profiles)
    return profiles.map(publicProfile)
  })
}

export async function resolveProfile(id: string | undefined, legacy: { apiUrl: string; apiKey: string }): Promise<{ apiUrl: string; apiKey: string; model?: string }> {
  const profiles = await readAll()
  const selected = id === undefined ? undefined : profiles.find(profile => profile.id === id)
  if (selected !== undefined) return { apiUrl: selected.apiUrl, apiKey: selected.apiKey, model: selected.model }
  return legacy
}
